import {confirmReset} from './confirm-reset.mjs';
import {ownRecord} from './state-validation.mjs';
export const balanceActivity={id:'balance',stage:'7y',key:'7y:balance',area:'Ciencia',type:'digital',label:'9–12 años · modelo ideal',kind:'interactive',title:'Física · Laboratorio de equilibrio',unit:'Una balanza, varias soluciones',copy:'Predice, mueve una distancia y compara el efecto. Explora distintas formas de equilibrar un modelo ideal.',goal:'Relacionar masa y distancia al apoyo; comparar una predicción con el resultado calculado, sin confundir el modelo con un experimento real.',duration:'Una serie a tu ritmo · puedes parar',support:'Lectura, cálculo y controles acompañados si hace falta',transfer:'Fuera de pantalla, dibuja una barra y marca su centro. Inventa dos pares de masa y distancia con el mismo producto, y compruébalos con papel o calculadora. No construyas una balanza ni cuelgues objetos.'};
export const balancePredictions={left:'Baja inicialmente la izquierda',equal:'Permanece horizontal en reposo',right:'Baja inicialmente la derecha'};
export const balanceReasons={products:'Comparo masa × distancia a ambos lados del apoyo.',mass:'Solo importa cuál masa es mayor.',compensate:'Para equilibrar, una masa menor puede estar más lejos y dar el mismo producto.',distance:'Basta con que ambas masas estén a la misma distancia.'};
export const newBalance=()=>({page:'guide',mass:3,distance:1,prediction:null,hint:false,original:null,last:null,reason:null,reviewed:false,comparison:null});
export function balanceResult(mass,distance){if(![1,2,3].includes(mass)||!Number.isInteger(distance)||distance<1||distance>6)throw Error('Invalid balance configuration');const left=6,right=mass*distance;return {left,right,outcome:left===right?'equal':left>right?'left':'right',leftTorque:58.8,rightTorque:Math.round(right*9.8*10)/10};}
function trial(raw){ownRecord(raw,['distance','prediction']);if(!Number.isInteger(raw.distance)||raw.distance<1||raw.distance>6||typeof raw.prediction!=='string'||!Object.hasOwn(balancePredictions,raw.prediction))throw Error('Invalid trial');return {distance:raw.distance,prediction:raw.prediction};}
export function validateBalance(s){
 const hasComparison=Object.hasOwn(s,'comparison');ownRecord(s,['page','mass','distance','prediction','hint','original','last','reason','reviewed',...(hasComparison?['comparison']:[])]);const comparison=hasComparison&&s.comparison!==null?validateBalanceReference(s.comparison):null;const baseline=comparison?comparison.last.distance:1;balanceResult(s.mass,s.distance);
 if(!['guide','lab','close'].includes(s.page)||typeof s.hint!=='boolean'||typeof s.reviewed!=='boolean'||!(s.prediction===null||typeof s.prediction==='string'&&Object.hasOwn(balancePredictions,s.prediction))||!(s.reason===null||typeof s.reason==='string'&&Object.hasOwn(balanceReasons,s.reason)))throw Error('Invalid balance state');
 const original=s.original===null?null:trial(s.original),last=s.last===null?null:trial(s.last);
 if(!!original!==!!last||original&&original.distance!==baseline||!original&&s.distance!==baseline||s.reviewed&&!s.reason||s.reason&&(!last||last.distance===baseline&&!comparison||s.distance!==last.distance||s.prediction!==last.prediction)||s.page==='guide'&&(original||s.distance!==baseline||s.prediction!==null||s.hint||s.reason||s.reviewed)||s.page==='close'&&(!last||last.distance===baseline&&!comparison||s.distance!==last.distance||s.prediction!==last.prediction||!s.reason||!s.reviewed))throw Error('Inconsistent balance state');
 if(last&&s.distance===last.distance&&s.prediction!==last.prediction)throw Error('Changed prediction for tested configuration');
 if(s.reviewed&&(!last||s.distance!==last.distance||s.prediction!==last.prediction))throw Error('Unmeasured review');
 if(comparison&&s.mass===comparison.mass)throw Error('Second series must change mass');return {...s,original,last,...(hasComparison?{comparison}: {})};
}
export const balanceBaseline=s=>s.comparison?.last.distance??1;
export function validateBalanceReference(r){ownRecord(r,['mass','original','last','reason']);const last=trial(r.last),original=trial(r.original);const a=validateBalance({page:'close',mass:r.mass,distance:last.distance,prediction:last.prediction,hint:false,original,last,reason:r.reason,reviewed:true});return {mass:a.mass,original:a.original,last:a.last,reason:a.reason};}
export function startBalanceComparison(s){if(s.page!=='close'||s.comparison)return false;const reference=validateBalanceReference({mass:s.mass,original:s.original,last:s.last,reason:s.reason});Object.assign(s,newBalance(),{comparison:reference,mass:[1,2,3].find(m=>m!==reference.mass),distance:reference.last.distance});return true;}
export function compareBalanceSeries(s){if(!s.comparison||!s.original)return null;const a=s.comparison,b=s.original;return {distance:a.last.distance,left:balanceResult(a.mass,a.last.distance),right:balanceResult(s.mass,b.distance),changed:['masa derecha'],fixed:['masa y distancia izquierdas','distancia derecha inicial','gravedad y apoyo']};}
export function moveBalance(s,distance){if(s.page!=='lab'||!s.original||!Number.isInteger(distance)||distance<1||distance>6||distance===s.distance)return false;s.distance=distance;s.prediction=s.last?.distance===distance?s.last.prediction:null;s.reason=null;s.reviewed=false;return true;}
export function testBalance(s){if(s.page!=='lab'||typeof s.prediction!=='string'||!Object.hasOwn(balancePredictions,s.prediction))return false;const t={distance:s.distance,prediction:s.prediction};if(!s.original)s.original={...t};s.last={...t};s.reason=null;s.reviewed=false;return true;}
export function explainBalance(s){if(!s.last)return 'Prueba una configuración antes de explicar.';const r=balanceResult(s.mass,s.last.distance);if(s.reason==='products')return `La comparación es pertinente: izquierda 2 × 3 = ${r.left} kg·m; derecha ${s.mass} × ${s.last.distance} = ${r.right} kg·m. ${r.outcome==='equal'?'Son iguales: los efectos de giro se compensan.':'Son distintos: esta configuración todavía no equilibra.'}`;if(s.reason==='compensate')return `Es una relación válida para buscar equilibrio. ${r.outcome==='equal'?'Aquí ambos productos valen 6 kg·m.':'Aquí aún no se igualan: '+r.left+' frente a '+r.right+' kg·m.'} No basta con alejar cualquier cantidad: comprueba el producto.`;if(s.reason==='mass')return 'La masa importa, pero también su distancia al apoyo. Dos masas distintas pueden compensarse si sus productos masa × distancia coinciden.';if(s.reason==='distance')return 'Distancias iguales solo equilibran este modelo si también son iguales las masas. Compara ambos productos.';return 'Elige una explicación para contrastarla con los resultados.';}
export function closeBalance(s){if(s.page!=='lab'||!s.last||s.last.distance===balanceBaseline(s)&&!s.comparison||s.distance!==s.last.distance||s.prediction!==s.last.prediction||!s.reason||!s.reviewed)return false;s.page='close';return true;}
const fmt=n=>String(n).replace('.',',');
const diagram=(mass,distance,outcome)=>{const x=350+distance*43;return `<svg class="balance-diagram" viewBox="0 0 700 245" role="img" aria-label="Barra horizontal con apoyo central. Izquierda: 2 kilogramos a 3 metros. Derecha: ${mass} kilogramos a ${distance} metros. ${outcome?balancePredictions[outcome]+'.':'Resultado todavía sin consultar.'}"><path d="M325 205L350 150L375 205Z" fill="#a2b68d" stroke="#344d41" stroke-width="3"/><path d="M65 150H635" stroke="#344d41" stroke-width="8"/>${Array.from({length:13},(_,i)=>{const xx=350+(i-6)*43;return `<path d="M${xx} 140V160" stroke="#344d41" stroke-width="2"/>`;}).join('')}<path d="M221 150V87M${x} 150V87" stroke="#344d41" stroke-width="3"/><rect x="166" y="34" width="110" height="54" rx="8" fill="#e4c596" stroke="#344d41" stroke-width="2"/><rect x="${x-55}" y="34" width="110" height="54" rx="8" fill="#c9d8be" stroke="#344d41" stroke-width="2"/><g fill="#183d33" text-anchor="middle" font-size="28"><text x="221" y="73">2 kg</text><text x="${x}" y="73">${mass} kg</text><text x="350" y="232">apoyo</text></g>${outcome&&outcome!=='equal'?`<path d="M${outcome==='left'?20:680} 30V95l-10-15m10 15 10-15" fill="none" stroke="#8d3e15" stroke-width="5"/>`:''}</svg>`;};
export function renderBalance(root,state,{finish}){
 const s=state.balance??=newBalance(),measured=!!s.last&&s.distance===s.last.distance&&s.prediction===s.last.prediction,r=measured?balanceResult(s.mass,s.distance):null;
 const redraw=(sel='#balance-title')=>{renderBalance(root,state,{finish});root.querySelector(sel)?.focus();};
 const choices=(values,selected,attr)=>`<div class="balance-choices">${Object.entries(values).map(([id,label])=>`<button type="button" class="action secondary" ${attr}="${id}" aria-pressed="${selected===id}">${label}</button>`).join('')}</div>`;
 const summary=(t,label,mass=s.mass)=>{const v=balanceResult(mass,t.distance);return `<article class="balance-record"><h5>${label}</h5><p>Izquierda fija: 2 kg a 3 m.</p><p>Derecha: ${mass} kg a ${t.distance} m.</p><p><strong>Predicción:</strong> ${balancePredictions[t.prediction]}.</p><p><strong>Resultado del modelo:</strong> ${balancePredictions[v.outcome]}.</p><p>Productos: 6 y ${v.right} kg·m.</p></article>`;};
 const pair=compareBalanceSeries(s);
 const comparisonView=pair?`<section class="balance-comparison" aria-labelledby="balance-comparison-title"><h5 id="balance-comparison-title">Dos series, una comparación controlada</h5><p><strong>Se mantiene:</strong> izquierda 2 kg a 3 m y distancia derecha ${pair.distance} m, apoyo y gravedad. <strong>Cambia solo:</strong> masa derecha, de ${s.comparison.mass} a ${s.mass} kg.</p><div class="balance-records">${summary(s.comparison.last,'Serie A · referencia conservada',s.comparison.mass)}${summary(s.original,'Serie B · primera predicción y resultado')}</div><p>Producto derecho A: ${pair.left.right} kg·m. Producto derecho B: ${pair.right.right} kg·m. ${pair.left.outcome===pair.right.outcome?'La tendencia inicial tiene el mismo sentido; eso no hace iguales los momentos.':'El cambio de masa cambia la tendencia inicial en esta comparación.'}</p><p>Después, dentro de B, solo cambias la distancia. Sus ajustes posteriores no son una comparación a distancia constante con A.</p></section>`:'';
 const intro=`<section class="balance-studio"><p class="eyebrow">Física · 9–12 años · simulación idealizada</p><h4 id="balance-title" tabindex="-1">Una balanza, varias soluciones</h4>`;
 const assumptions='<details class="balance-assumptions"><summary>Qué representa este modelo y qué deja fuera</summary><p>Barra rígida horizontal al inicio, masa de la barra despreciable, apoyo fijo ideal sin rozamiento y dos masas puntuales. La gravedad es uniforme. Partimos del reposo en cada prueba. La flecha muestra solo la tendencia inicial: no calculamos ángulo, velocidad, oscilación ni tiempo.</p><p>Las distancias son del apoyo a cada masa, en metros (m), y las masas en kilogramos (kg). Los bloques son símbolos; su tamaño no está a escala. No representa una balanza real ni sirve para construirla.</p><p>Para el adulto: peso = masa × g, con g = 9,8 m/s². Momento de fuerza = peso × distancia perpendicular, en N·m. En esta posición horizontal, el factor g es común: comparar masa × distancia permite comparar los momentos. kg·m es un producto auxiliar, no la unidad de fuerza ni de momento. En equilibrio, el apoyo también compensa la fuerza total.</p></details>';
 const bind=(id,fn)=>root.querySelector('#'+id)?.addEventListener('click',fn);
 if(s.page==='guide'){
 root.innerHTML=intro+(s.comparison?`<p class="notice">Serie A conservada. Para iniciar B, mantenemos la distancia derecha en ${balanceBaseline(s)} m y cambiamos solo la masa. Después podrás explorar distancias dentro de B.</p>`:'')+'<p>La izquierda tiene 2 kg a 3 m del apoyo. Elige una masa para la derecha. Durante la serie solo moverás su <strong>distancia</strong>; las dos masas quedarán fijas.</p>'+choices({1:'Derecha: 1 kg',2:'Derecha: 2 kg',3:'Derecha: 3 kg'},String(s.mass),'data-balance-mass')+diagram(s.mass,s.distance,null)+'<p>Primero predice qué pasará al soltar desde la posición horizontal. Después mueve la masa derecha, vuelve a predecir y prueba. Puedes encontrar una solución para cada masa elegida.</p>'+assumptions+'<button type="button" class="action primary" id="balance-start">Empezar esta serie</button></section>';
 root.querySelectorAll('[data-balance-mass]').forEach(b=>{if(s.comparison&&Number(b.dataset.balanceMass)===s.comparison.mass)b.disabled=true;b.onclick=()=>{s.mass=Number(b.dataset.balanceMass);redraw(`[data-balance-mass="${s.mass}"]`);};});bind('balance-start',()=>{s.page='lab';redraw();});return;
 }
 if(s.page==='close'){
 root.innerHTML=intro+comparisonView+'<p>En la serie actual, las masas permanecen fijas al explorar distancias. Una predicción distinta del resultado es una oportunidad para revisar el modelo; no hay puntuación.</p>'+(s.comparison?'<details><summary>Consultar intentos dentro de la serie B</summary>':'')+'<div class="balance-records">'+summary(s.original,'Intento inicial')+summary(s.last,'Último intento probado')+'</div>'+(s.comparison?'</details>':'')+'<p class="notice">'+explainBalance(s)+'</p><p><strong>Fuera de pantalla:</strong> dibuja una barra con apoyo central. Busca dos pares de masa y distancia con el mismo producto. Puedes usar una calculadora y pedir ayuda. No construyas una balanza ni cuelgues objetos.</p><div class="controls"><button type="button" class="action secondary" id="balance-revise">Seguir con esta serie</button>'+(!s.comparison?'<button type="button" class="action secondary" id="balance-compare-series">Conservar A y preparar serie B</button>':'')+'<button type="button" class="action secondary" id="balance-new">Empezar de nuevo: sustituir estas series</button><button type="button" class="action primary" id="balance-finish">Terminar por hoy</button></div>'+assumptions+'</section>';
 bind('balance-revise',()=>{s.page='lab';redraw();});bind('balance-compare-series',()=>{if(startBalanceComparison(s))redraw();});bind('balance-new',()=>confirmReset(root.querySelector('#balance-new'),{message:'Se borrarán los intentos y las series de esta balanza. ¿Sustituirlos por una serie nueva?',onConfirm:()=>{Object.assign(s,newBalance());redraw();}}));bind('balance-finish',finish);return;
 }
 root.innerHTML=intro+`${s.comparison?'<p class="notice">Serie B · A permanece guardada. La primera prueba de B compara masas a distancia constante.</p>':''}<p><strong>Fijo:</strong> izquierda 2 kg a 3 m; derecha ${s.mass} kg. <strong>Única variable:</strong> distancia derecha, de 1 a 6 m.</p>${diagram(s.mass,s.distance,r?.outcome)}<p class="balance-reading">Derecha: ${s.mass} kg a <strong>${s.distance} m</strong> del apoyo. Cada marca de la barra representa 1 m.</p><div class="controls"><button type="button" class="action secondary" id="balance-nearer" ${!s.original||s.distance===1?'disabled':''}>Acercar 1 m</button><button type="button" class="action secondary" id="balance-farther" ${!s.original||s.distance===6?'disabled':''}>Alejar 1 m</button></div>${!s.original?`<p>Primero registra la prueba inicial a ${balanceBaseline(s)} m. Después se activarán los controles de distancia.</p>`:''}${!measured?`<fieldset><legend>Predice antes de probar</legend>${choices(balancePredictions,s.prediction,'data-balance-prediction')}</fieldset><button type="button" class="action primary" id="balance-test" ${s.prediction===null?'disabled':''}>Probar esta configuración</button>`:'<p>Esta configuración ya está registrada. Mueve la distancia para hacer otra predicción.</p>'}<div id="balance-result" role="status" tabindex="-1">${r?`<p><strong>Resultado:</strong> ${balancePredictions[r.outcome]}.</p><p>${s.prediction===r.outcome?'Tu predicción coincide con este resultado.':'Tu predicción fue distinta. Compara los productos para revisar la explicación.'}</p><p>Izquierda: 2 × 3 = 6 kg·m. Derecha: ${s.mass} × ${s.distance} = ${r.right} kg·m.</p><p>${r.outcome==='equal'?'Los productos son iguales: se compensan los efectos de giro.':'El lado con mayor producto tiende a bajar inicialmente. No mostramos un ángulo final.'}</p><details><summary>Ver momentos de fuerza</summary><p>Izquierda: ${fmt(r.leftTorque)} N·m; derecha: ${fmt(r.rightTorque)} N·m. Se usa g = 9,8 m/s².</p></details>`:'<p>Resultado pendiente para esta distancia. La barra horizontal muestra la posición de partida, no un equilibrio confirmado.</p>'}</div><button type="button" class="action secondary" id="balance-hint">Una pista</button><p id="balance-hint-text" role="status" tabindex="-1">${s.hint?'Multiplica la masa por su distancia al apoyo. En la izquierda el producto es 6 kg·m. Busca una distancia derecha que dé también 6; no cambies la masa durante esta serie.':''}</p>${s.original?`<details><summary>Consultar el intento inicial</summary>${summary(s.original,'Referencia guardada')}</details>`:''}${measured&&(s.last.distance!==balanceBaseline(s)||s.comparison)?`<fieldset><legend>¿Qué relación explica lo que observas?</legend>${choices(balanceReasons,s.reason,'data-balance-reason')}</fieldset><button type="button" class="action secondary" id="balance-explain" ${!s.reason?'disabled':''}>Contrastar mi explicación</button><p id="balance-explanation" role="status" tabindex="-1">${s.reviewed?explainBalance(s):''}</p><button type="button" class="action primary" id="balance-close" ${!s.reviewed?'disabled':''}>Comparar intento inicial y final</button>`:''}<p class="quiet">Puedes terminar o pausar arriba, también sin alcanzar equilibrio. El cierre conserva las relaciones pendientes; no certifica que hayas dominado el tema.</p>${pair?'<details><summary>Consultar comparación entre series</summary>'+comparisonView+'</details>':''}${assumptions}</section>`;
 bind('balance-nearer',()=>{if(moveBalance(s,s.distance-1))redraw(s.distance===1?'#balance-farther':'#balance-nearer');});bind('balance-farther',()=>{if(moveBalance(s,s.distance+1))redraw(s.distance===6?'#balance-nearer':'#balance-farther');});
 root.querySelectorAll('[data-balance-prediction]').forEach(b=>b.onclick=()=>{s.prediction=b.dataset.balancePrediction;redraw(`[data-balance-prediction="${s.prediction}"]`);});
 bind('balance-test',()=>{if(testBalance(s))redraw('#balance-result');});bind('balance-hint',()=>{s.hint=true;redraw('#balance-hint-text');});
 root.querySelectorAll('[data-balance-reason]').forEach(b=>b.onclick=()=>{s.reason=b.dataset.balanceReason;s.reviewed=false;redraw(`[data-balance-reason="${s.reason}"]`);});
 bind('balance-explain',()=>{s.reviewed=true;redraw('#balance-explanation');});bind('balance-close',()=>{if(closeBalance(s))redraw();});
}
